@Override
    public MediaType detect(TikaInputStream tis, Metadata metadata, ParseContext parseContext)
            throws IOException {
        if (tis != null) {
            try {
                tis.mark(1);
                if (tis.read() == -1) {
                    return MediaType.EMPTY;
                }
            } finally {
                tis.reset();
            }
        }
        return MediaType.OCTET_STREAM;
    }

